     qmlRegisterSingletonInstance("org.kde.bluedevil.kcm", 1, 0, "GlobalSettings", GlobalSettings::self());
+
+#if HAVE_NETWORKMANAGERQT
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::activeConnectionAdded, this, &Bluetooth::internetSharingChanged);
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::activeConnectionRemoved, this, &Bluetooth::internetSharingChanged);
