@@ -149,6 +166,110 @@ void Bluetooth::setReceiveFolderPath(const QString &path)
     Q_EMIT receiveFolderPathChanged();
 }

+bool Bluetooth::internetSharingAvailable() const
+{
+#if HAVE_NETWORKMANAGERQT
+    return NetworkManager::status() != NetworkManager::Unknown;
+#else
+    return false;
+#endif
+}
+
+bool Bluetooth::internetSharing() const
+{
+#if HAVE_NETWORKMANAGERQT
+    const QString uuid = GlobalSettings::internetSharingConnection();
+    if (uuid.isEmpty()) {
+        return false;
+    }
+
+    const NetworkManager::ActiveConnection::List activeConnections = NetworkManager::activeConnections();
+    return std::any_of(activeConnections.cbegin(), activeConnections.cend(), [&uuid](const NetworkManager::ActiveConnection::Ptr &activeConnection) {
+        return activeConnection->uuid() == uuid;
+    });
+#else
+    return false;
+#endif
+}
+
+void Bluetooth::setInternetSharing(bool enable)
+{
+#if HAVE_NETWORKMANAGERQT
+    NetworkManager::Connection::Ptr connection = NetworkManager::findConnectionByUuid(GlobalSettings::internetSharingConnection());
+
+    if (!enable) {
+        if (connection) {
+            connection->remove();
+        }
+        GlobalSettings::setInternetSharingConnection(QString());
+        GlobalSettings::self()->save();
+        return;
+    }
+
+    if (connection) {
+        activateInternetSharing(connection->path());
+        return;
+    }
+
+    // A bridge with a Bluetooth NAP setting makes NetworkManager register the network
+    // server with BlueZ, and the shared method gives connected devices DHCP and NAT
+    NetworkManager::ConnectionSettings settings(NetworkManager::ConnectionSettings::Bridge);
+    settings.setId(i18nc("@title NetworkManager connection name", "Bluetooth Internet Sharing"));
+    settings.setUuid(NetworkManager::ConnectionSettings::createNewUuid());
+    settings.setInterfaceName(QStringLiteral("pan0"));
+
+    auto bridge = settings.setting(NetworkManager::Setting::Bridge).staticCast<NetworkManager::BridgeSetting>();
+    bridge->setStp(false);
+    bridge->setInitialized(true);
+
+    auto bluetooth = settings.setting(NetworkManager::Setting::Bluetooth).staticCast<NetworkManager::BluetoothSetting>();
+    bluetooth->setProfileType(NetworkManager::BluetoothSetting::Nap);
+    bluetooth->setInitialized(true);
+
+    auto ipv4 = settings.setting(NetworkManager::Setting::Ipv4).staticCast<NetworkManager::Ipv4Setting>();
+    ipv4->setMethod(NetworkManager::Ipv4Setting::Shared);
+    ipv4->setInitialized(true);
+
+    auto ipv6 = settings.setting(NetworkManager::Setting::Ipv6).staticCast<NetworkManager::Ipv6Setting>();
+    ipv6->setMethod(NetworkManager::Ipv6Setting::Ignored);
+    ipv6->setInitialized(true);
+
+    const QString uuid = settings.uuid();
+    // NetworkManager creates the bridge itself, so there is no device to activate it on
+    auto *watcher = new QDBusPendingCallWatcher(NetworkManager::addAndActivateConnection(settings.toMap(), QStringLiteral("/"), QString()), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, uuid](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        QDBusPendingReply<QDBusObjectPath, QDBusObjectPath> reply = *watcher;
+        if (reply.isError()) {
+            Q_EMIT errorOccured(reply.error().message());
+        } else {
+            GlobalSettings::setInternetSharingConnection(uuid);
+            GlobalSettings::self()->save();
+        }
+        Q_EMIT internetSharingChanged();
+    });
+#else
+    Q_UNUSED(enable)
+#endif
+}
+
+void Bluetooth::activateInternetSharing(const QString &connectionPath)
+{
+#if HAVE_NETWORKMANAGERQT
+    auto *watcher = new QDBusPendingCallWatcher(NetworkManager::activateConnection(connectionPath, QString(), QString()), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        QDBusPendingReply<QDBusObjectPath> reply = *watcher;
+        if (reply.isError()) {
+            Q_EMIT errorOccured(reply.error().message());
+        }
+        Q_EMIT internetSharingChanged();
+    });
+#else
+    Q_UNUSED(connectionPath)
+#endif
+}
+
 #include "bluetooth.moc"

 #include "moc_bluetooth.cpp"
