From 2df5bf9e6576fa0e93aaf402326715bbb2044d4b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:24:06 +0100
Subject: [PATCH] settings: support Bluetooth NAP settings on bridge
 connections

NetworkManager serves a Bluetooth network through a bridge connection with
a bluetooth setting of type "nap", but bridges dropped that setting and the
profile type had no value for it. Add the Nap type and keep the setting.

BUG: 523139
---
 src/settings/bluetoothsetting.cpp   | 11 +++++++++++
 src/settings/bluetoothsetting.h     |  2 ++
 src/settings/connectionsettings.cpp |  2 ++
 3 files changed, 15 insertions(+)

diff --git a/src/settings/bluetoothsetting.cpp b/src/settings/bluetoothsetting.cpp
index ae44884..db82672 100644
--- a/src/settings/bluetoothsetting.cpp
+++ b/src/settings/bluetoothsetting.cpp
@@ -7,8 +7,14 @@
 #include "bluetoothsetting.h"
 #include "bluetoothsetting_p.h"

+#include <nm-version.h>
+
 #include <QDebug>

+#if !NM_CHECK_VERSION(1, 12, 0)
+#define NM_SETTING_BLUETOOTH_TYPE_NAP "nap"
+#endif
+
 NetworkManager::BluetoothSettingPrivate::BluetoothSettingPrivate()
     : name(NM_SETTING_BLUETOOTH_SETTING_NAME)
     , profileType(BluetoothSetting::Unknown)
@@ -82,6 +88,8 @@ void NetworkManager::BluetoothSetting::fromMap(const QVariantMap &setting)
             setProfileType(Dun);
         } else if (type == QLatin1String(NM_SETTING_BLUETOOTH_TYPE_PANU)) {
             setProfileType(Panu);
+        } else if (type == QLatin1String(NM_SETTING_BLUETOOTH_TYPE_NAP)) {
+            setProfileType(Nap);
         }
     }
 }
@@ -101,6 +109,9 @@ QVariantMap NetworkManager::BluetoothSetting::toMap() const
     case Panu:
         setting.insert(QLatin1String(NM_SETTING_BLUETOOTH_TYPE), QLatin1String(NM_SETTING_BLUETOOTH_TYPE_PANU));
         break;
+    case Nap:
+        setting.insert(QLatin1String(NM_SETTING_BLUETOOTH_TYPE), QLatin1String(NM_SETTING_BLUETOOTH_TYPE_NAP));
+        break;
     case Unknown:
         break;
     }
diff --git a/src/settings/bluetoothsetting.h b/src/settings/bluetoothsetting.h
